'use strict';

const { Resource } = require('./Resource');

class Data extends Resource {
    plans() {
        return this._client.get('products/internet');
    }

    purchase({ phone, productCode, reference }) {
        return this._client.post('purchases/data', {
            phone,
            product_code: productCode,
            reference,
        });
    }
}

module.exports = { Data };
